from acmesdk.scheduler import compose_window
result = compose_window(['tango', 'flint', 'pixel', 'alpha', 'flint'])
result = {'value': result}
assert result == {'value': 'TANGO FLINT PIXEL ALPHA FLINT'}
print('Success')

from acmesdk.storage import collect_chunk
result = collect_chunk({'id': 1, 'name': 'nova', 'tier': 'a'}, ['id', 'name', 'owner'])
result = {'value': result}
assert result == {'value': {'id': 1, 'name': 'nova', 'owner': None}}
print('Success')

